-- v3d01_transaction_atomicity / ex2 — recovering from the aborted state
BEGIN;

UPDATE accounts
   SET balance = balance - 600.00
 WHERE id = 1;

INSERT INTO ledger (account_id, delta, note)
VALUES (1, -600.00, 'escrow leg 1');

-- INJECT FAILURE HERE

-- The transaction is aborted. ROLLBACK is the only statement that both
-- ends the block and is honest about what happened to the work.
ROLLBACK;

-- v3d01_transaction_atomicity / ex3 — a batch that survives its poison rows
DO $$
DECLARE
  r        record;
  applied  int := 0;
  rejected int := 0;
BEGIN
  FOR r IN SELECT * FROM import_rows ORDER BY id LOOP
    -- This nested BEGIN block is a savepoint. Everything the body writes
    -- is discarded before the EXCEPTION branch runs.
    BEGIN
      UPDATE accounts
         SET balance = balance + r.delta
       WHERE id = r.account;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'no such account %', r.account;
      END IF;

      INSERT INTO ledger (account_id, delta, note)
      VALUES (r.account, r.delta, 'import ' || r.id);

      applied := applied + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO import_rejects (row_id, sqlstate, message)
      VALUES (r.id, SQLSTATE, SQLERRM);
      rejected := rejected + 1;
    END;
  END LOOP;

  RAISE NOTICE 'import finished: % applied, % rejected', applied, rejected;
END $$;

-- v3d01_transaction_atomicity / ex4 — savepoint stacks
-- Prediction: 'a' and 'e' survive. 'c' dies at step 7; 'b' and 'd' die at
-- step 10, because RELEASE uncovered the outer savepoint named s.
BEGIN;

INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'a');

SAVEPOINT s;                       -- outer s
INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'b');

SAVEPOINT s;                       -- inner s, hides the outer one
INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'c');

ROLLBACK TO SAVEPOINT s;           -- drops 'c'; inner s still exists
INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'd');

RELEASE SAVEPOINT s;               -- pops inner s, keeps 'd' for now
ROLLBACK TO SAVEPOINT s;           -- reaches the OUTER s: 'b' and 'd' go

INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'e');

COMMIT;

-- v3d01_transaction_atomicity / ex5 — deferring uniqueness to swap two seats
BEGIN;

-- DDL is transactional, so re-declaring the constraint is part of the
-- same unit of work and vanishes if anything below fails.
ALTER TABLE seats DROP CONSTRAINT seats_pk;
ALTER TABLE seats ADD CONSTRAINT seats_pk
  PRIMARY KEY (event_id, seat_no) DEFERRABLE INITIALLY IMMEDIATE;

SET CONSTRAINTS seats_pk DEFERRED;

UPDATE seats SET seat_no = 3 WHERE event_id = 1 AND seat_no = 2;   -- 'b'
UPDATE seats SET seat_no = 2 WHERE event_id = 1 AND seat_no = 3
                                AND holder = 'c';

COMMIT;   -- uniqueness of (event_id, seat_no) is verified here

-- v3d01_transaction_atomicity / ex6 — transactional DDL, proven
BEGIN;

CREATE TABLE fee_schedule (
  tier int PRIMARY KEY,
  pct  numeric(5,4) NOT NULL
);

INSERT INTO fee_schedule (tier, pct) VALUES (1, 0.0100), (2, 0.0250);

ALTER TABLE accounts ADD COLUMN fee_tier int NOT NULL DEFAULT 1;

ALTER TABLE accounts ADD CONSTRAINT accounts_fee_tier_fkey
  FOREIGN KEY (fee_tier) REFERENCES fee_schedule(tier);

ROLLBACK;

-- Nothing above survived: the catalog changes were part of the same
-- transaction as the data changes.
SELECT to_regclass('public.fee_schedule') IS NULL AS table_gone,
       NOT EXISTS (
         SELECT 1
           FROM information_schema.columns
          WHERE table_name  = 'accounts'
            AND column_name = 'fee_tier'
       ) AS column_gone;

-- v3d01_transaction_atomicity / ex7 — an exception handler is a subtransaction
DO $$
DECLARE
  outer_xid text;
  inner_xid text;
BEGIN
  -- The first write assigns the top-level transaction id.
  INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'probe outer');
  outer_xid := pg_current_xact_id()::text;

  -- The EXCEPTION clause makes this block a subtransaction; its first
  -- write assigns a child transaction id.
  BEGIN
    INSERT INTO ledger (account_id, delta, note) VALUES (1, 0.00, 'probe inner');
    inner_xid := pg_current_xact_id()::text;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  INSERT INTO xid_probe (step, xid)
  VALUES ('outer', outer_xid), ('inner', inner_xid);
END $$;

-- v3d01_transaction_atomicity / challenge — an importer safe to run twice
DO $$
DECLARE
  r        record;
  applied  int := 0;
  rejected int := 0;
  skipped  int := 0;
  key      text;
BEGIN
  FOR r IN SELECT * FROM import_rows ORDER BY id LOOP
    key := 'import ' || r.id;

    -- Idempotency guards come BEFORE any side effect. A record already
    -- applied, or already rejected, is finished business.
    IF EXISTS (SELECT 1 FROM ledger WHERE note = key)
       OR EXISTS (SELECT 1 FROM import_rejects WHERE row_id = r.id) THEN
      skipped := skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      UPDATE accounts
         SET balance = balance + r.delta
       WHERE id = r.account;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'no such account %', r.account;
      END IF;

      INSERT INTO ledger (account_id, delta, note)
      VALUES (r.account, r.delta, key);

      applied := applied + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO import_rejects (row_id, sqlstate, message)
      VALUES (r.id, SQLSTATE, SQLERRM);
      rejected := rejected + 1;
    END;
  END LOOP;

  RAISE NOTICE 'applied %, rejected %, skipped %', applied, rejected, skipped;
END $$;

-- v3d01_transaction_atomicity / review1 — inspect your own work, then decide
DO $$
DECLARE
  before_total numeric;
  after_total  numeric;
  amt          numeric;
BEGIN
  SELECT sum(balance) INTO before_total FROM accounts;
  SELECT balance      INTO amt          FROM accounts WHERE id = 1;

  UPDATE accounts SET balance = balance - amt WHERE id = 1;
  UPDATE accounts SET balance = balance + amt WHERE id = 3;

  INSERT INTO ledger (account_id, delta, note)
  VALUES (1, -amt, 'sweep'), (3, amt, 'sweep');

  -- Our own uncommitted writes are visible to us and to nobody else.
  SELECT sum(balance) INTO after_total FROM accounts;

  IF after_total <> before_total THEN
    RAISE EXCEPTION 'invariant broken: % -> %', before_total, after_total;
  END IF;
END $$;

