DO $$
DECLARE
  before_write text;
  after_write  text;
BEGIN
  PERFORM count(*) FROM widget;                    -- a read assigns nothing
  before_write := (pg_current_xact_id_if_assigned() IS NOT NULL)::text;

  INSERT INTO widget (id, name, qty) VALUES (99, 'probe', 0);
  after_write  := (pg_current_xact_id_if_assigned() IS NOT NULL)::text;

  DELETE FROM widget WHERE id = 99;                -- leave the table as found

  INSERT INTO observation (label, value)
  VALUES ('assigned_before_write', before_write),
         ('assigned_after_write',  after_write);
END $$;

