-- v3d03_isolation_levels / ex8 — retrying inside the transaction is futile
-- @A
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT n FROM counter WHERE name = 'hits';       -- snapshot taken here

-- @B
UPDATE counter SET n = n + 1 WHERE name = 'hits';

-- @A
DO $$
DECLARE
  i       int;
  outcome text;
BEGIN
  FOR i IN 1..3 LOOP
    BEGIN
      UPDATE counter SET n = n + 1 WHERE name = 'hits';
      outcome := 'succeeded';
    EXCEPTION WHEN serialization_failure THEN
      outcome := '40001';          -- the subtransaction absorbed it
    END;
    INSERT INTO observation (label, value) VALUES ('attempt_' || i, outcome);
  END LOOP;
END $$;
COMMIT;

-- @A
BEGIN ISOLATION LEVEL REPEATABLE READ;           -- a new snapshot at last
UPDATE counter SET n = n + 1 WHERE name = 'hits';
COMMIT;

-- @A
INSERT INTO observation (label, value)
SELECT 'final_n', n::text FROM counter WHERE name = 'hits';

-- v3d03_isolation_levels / challenge — locking the read set at READ COMMITTED
CREATE OR REPLACE FUNCTION try_go_off_call(p_name text)
RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
  remaining int;
BEGIN
  -- Lock the whole read set the decision depends on, in a deterministic
  -- order so two callers can never take these locks in opposite orders.
  PERFORM 1 FROM doctor WHERE on_call ORDER BY name FOR UPDATE;

  SELECT count(*) INTO remaining
    FROM doctor
   WHERE on_call AND name <> p_name;

  IF remaining < 1 THEN
