CREATE OR REPLACE FUNCTION safe_transfer(p_from int, p_to int, p_amt numeric)
RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
  src numeric;
BEGIN
  IF p_from = p_to THEN
    RETURN false;
  END IF;

  -- Canonical order: ascending id, whatever direction the money moves.
  PERFORM 1 FROM account WHERE id = least(p_from, p_to)    FOR UPDATE;
  PERFORM 1 FROM account WHERE id = greatest(p_from, p_to) FOR UPDATE;

  SELECT balance INTO src FROM account WHERE id = p_from;
  IF src < p_amt THEN
    RETURN false;
  END IF;

  UPDATE account SET balance = balance - p_amt WHERE id = p_from;
  UPDATE account SET balance = balance + p_amt WHERE id = p_to;

  INSERT INTO ledger (account_id, delta, note)
  VALUES (p_from, -p_amt, 'xfer ' || p_from || '->' || p_to),
         (p_to,    p_amt, 'xfer ' || p_from || '->' || p_to);

  RETURN true;
END $$;

